const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const china = ee.Geometry.Rectangle([73.5, 18.0, 135.0, 53.5]); // China bounding box

  // 2. Data Acquisition - MODIS NDVI
  const modis2000 = ee.ImageCollection('MODIS/061/MOD13A1')
    .filterBounds(china)
    .filterDate('2000-01-01', '2000-12-31')
    .select('NDVI');

  const modis2017 = ee.ImageCollection('MODIS/061/MOD13A1')
    .filterBounds(china)
    .filterDate('2017-01-01', '2017-12-31')
    .select('NDVI');

  // Check collection sizes
  const size2000 = modis2000.size().getInfo();
  const size2017 = modis2017.size().getInfo();

  console.log(`2000 Images: ${size2000}, 2017 Images: ${size2017}`);

  if (size2000 === 0 || size2017 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create annual mean composites
  const ndvi2000 = modis2000.mean().multiply(0.0001); // Scale factor for MODIS NDVI
  const ndvi2017 = modis2017.mean().multiply(0.0001);

  // 3. Check valid pixels
  const count2000 = ndvi2000.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: china,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2017 = ndvi2017.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: china,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Valid pixels - 2000: ${count2000}, 2017: ${count2017}`);

  if (count2000 === 0 || count2017 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculate mean NDVI values
  const mean2000 = ndvi2000.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: china,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const mean2017 = ndvi2017.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: china,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Mean NDVI - 2000: ${mean2000?.toFixed(4)}, 2017: ${mean2017?.toFixed(4)}`);

  // 5. Validation & Final Answer
  if (mean2000 === null || mean2017 === null || 
      isNaN(mean2000) || isNaN(mean2017) ||
      mean2000 < -1 || mean2000 > 1 || mean2017 < -1 || mean2017 > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  const ndviChange = mean2017 - mean2000;
  console.log(`NDVI Change: ${ndviChange.toFixed(4)}`);

  if (ndviChange > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
